const $=s=>document.querySelector(s),roles=['기획','프로그래밍','아트','QA','사업·마케팅'];
const jobs={기획:['첫 플레이의 목표 설계','테스터가 길을 잃어요. 첫 목표와 안내 방식을 정해주세요.','작은 체험으로 규칙 익히기','설명 문구를 빠르게 보완'],프로그래밍:['조작 지연의 원인 조사','편지를 배달할 때 입력이 늦게 반응해요. 원인을 찾아주세요.','입력 처리 구조 개선','데모 구간에 한정해 수정'],아트:['별빛 마을의 가독성 개선','예쁜 배경에 우체통이 묻혀요. 시선을 이끌 방법이 필요해요.','색과 실루엣을 함께 개선','우체통에 강조 효과 추가'],QA:['사라진 편지 재현하기','저장 후 편지가 사라졌다는 제보가 왔어요. 재현 조건을 찾아주세요.','저장과 종료 조건 체계적으로 검증','가장 흔한 경로부터 확인'], '사업·마케팅':['첫 데모의 타깃 찾기','탐험을 좋아하는 유저에게 우리 게임을 어떻게 소개할까요?','플레이 반응 조사 후 메시지 제작','현재 영상으로 소규모 홍보']};
let state;try{state=JSON.parse(localStorage.getItem('studio-days-v1'))}catch{};let view='office',player={x:720,y:744},target={...player},notice='';
const fresh=(name,role,path)=>({name,role,path,turn:0,quality:18,stability:22,trust:45,fatigue:8,money:path==='founder'?1800:4200,xp:0,done:false,logs:['첫 공개 데모까지 4주. 별빛 우체부 팀에 합류했다.']});
function save(){localStorage.setItem('studio-days-v1',JSON.stringify(state))}function time(){return `${Math.floor(state.turn/3)+1}일차 ${['오전','오후','저녁'][state.turn%3]}`}function stage(){return Math.min(3,Math.floor(state.turn/21))}const stages=['프로토타입','프리 데모 · 내부 검증','공개 데모 제작','최종 점검 · 공개'];
function render(){if(!state)return;$('#clock').textContent=`1년차 · ${time()}`;$('#slot').textContent=['오전 업무','오후 업무','저녁 활동'][state.turn%3];$('#identity').textContent=`${state.name} · ${state.role} · ${state.path==='founder'?'공동 창업자':state.xp>=100?'파트 리더':'팀원'}`;$('#days').textContent=`D−${Math.max(0,28-Math.floor(state.turn/3))}`;$('#stages').innerHTML=stages.map((s,i)=>`<div class="stage ${i===stage()?'current':i<stage()?'done':''}">${i<stage()?'✓':i===stage()?'●':'○'} ${s}</div>`).join('');$('#stats').innerHTML=[['운영 자금',`${state.money.toLocaleString()}만`,state.money/50],['게임 완성도',state.quality+'%',state.quality],['팀 신뢰',state.trust,state.trust],['나의 피로',state.fatigue+' / 100',state.fatigue]].map(([a,b,c])=>`<div class="stat"><span>${a}</span><b>${b}</b><div class="bar"><i style="width:${Math.min(100,c)}%;background:${a==='나의 피로'?'#ca9d68':'#5d9b89'}"></i></div></div>`).join('');const j=jobs[state.role];$('#tasks').innerHTML=state.done?'<div class="report"><h3>첫 데모 공개 완료!</h3><p>결과를 확인하거나 새 커리어로 다른 직군을 경험해 보세요.</p><button class="primary" onclick="ending()">결과 보기</button></div>':`<button class="task" onclick="openTask('work')"><span class="tag">${state.role} · ${stages[stage()]}</span><b>${j[0]}</b><p>${j[1]}</p><small>◷ 1구간부터 · 전문성 성장</small></button><button class="task" onclick="openTask('collab')"><span class="tag">부서 간 협업</span><b>같이 풀면 보이는 문제</b><p>동료와 빌드를 살펴보고 다음 작업의 우선순위를 맞춰요.</p><small>◷ 1구간 · 팀 신뢰 +8</small></button><button class="task" onclick="openTask('manage')"><span class="tag">${state.path==='founder'?'경영 결정':'팀에 제안하기'}</span><b>${state.path==='founder'?'이번 주의 자원 배분':'데모 범위 조정 제안'}</b><p>${state.path==='founder'?'외부 지원을 받을지, 팀의 힘으로 범위를 줄일지 결정해요.':'무엇을 남길지 근거를 모아 팀에 제안해요.'}</p><small>◷ 1구간 · 비용과 일정 조율</small></button>`;if(view!=='office')renderOther();save()}
function show(title,body,options=[]){$('#detailContent').innerHTML=`<span class="eyebrow">별빛 우체부 개발팀</span><h2>${title}</h2><p>${body}</p><div id="options"></div>`;options.forEach(o=>{let b=document.createElement('button');b.className='option';b.innerHTML=`<b>${o.label}</b><small>${o.effect}</small>`;b.onclick=()=>{$('#detail').close();o.run()};$('#options').append(b)});$('#detail').showModal()}
function advance(cost,delta,text){if(state.done)return;const remaining=84-state.turn;if(cost>remaining){show('남은 시간이 부족해요',`공개까지 ${remaining}구간 남았어요. 짧은 업무를 선택해 주세요.`);return}state.turn+=cost;for(let [k,v]of Object.entries(delta))state[k]+=v;for(let k of ['quality','stability','trust','fatigue'])state[k]=Math.max(0,Math.min(100,state[k]));state.money=Math.max(0,state.money-20*cost);state.logs.unshift(`${time()} · ${text}`);$('#messageTitle').textContent='업무 결과';$('#message').textContent=text;render();if(state.turn>=84){state.done=true;render();ending()}else if(state.fatigue>=85){show('잠깐 숨을 돌릴 때예요','피로가 높아 업무의 효과가 줄어들어요. 휴게실에서 쉬면 다시 집중할 수 있어요.')}else if(state.turn%21<cost){show('다음 개발 단계로',`${stages[stage()]} 단계에 도착했어요. ${['','팀 내부에서 핵심 재미를 검증합니다.','외부 유저가 이해할 수 있는 데모를 제작합니다.','출시 위험과 첫인상을 마지막으로 점검합니다.'][stage()]}`)}}
function openTask(type){if(state.done){ending();return}const j=jobs[state.role],gain=state.fatigue>=85?4:8;if(type==='work')show(j[0],j[1]+' 충분히 검증하면 품질이 더 좋아지지만 시간이 더 필요해요.',[{label:j[2],effect:'2구간 · 완성도 +'+gain+' · 안정성 +8 · 피로 +12',run:()=>advance(2,{quality:gain,stability:8,fatigue:12,xp:8},'충분한 조사와 검증으로 문제를 개선했다. 완성도와 안정성이 함께 올랐다.')},{label:j[3],effect:'1구간 · 완성도 +4 · 안정성 +2 · 피로 +8',run:()=>advance(1,{quality:4,stability:2,fatigue:8,xp:4},'데모 범위에 맞춰 빠르게 개선했다. 더 넓은 검증은 다음 과제로 남았다.')}]);if(type==='collab')show('같이 풀면 보이는 문제','QA 수현이 첫 플레이에서 목표를 놓치는 장면을 발견했어요. 기획·아트·개발이 함께 해결할까요?',[{label:'함께 빌드를 보고 개선점 합의',effect:'1구간 · 팀 신뢰 +8 · 완성도 +3 · 피로 +4',run:()=>advance(1,{trust:8,quality:3,fatigue:4,xp:3},'동료들과 문제의 맥락을 공유했다. 다음 작업의 방향이 명확해졌다.')},{label:'작은 테스트를 나눠 맡기',effect:'2구간 · 안정성 +12 · 신뢰 +5 · 피로 +6',run:()=>advance(2,{stability:12,trust:5,fatigue:6,xp:5},'부서별 관찰을 모아 재현 조건과 수정 우선순위를 정했다.')}]);if(type==='manage'){const founder=state.path==='founder';show(founder?'이번 주의 자원 배분':'데모 범위 조정 제안',founder?'제작 자원이 부족해요. 외부 제작 지원을 받거나 핵심 기능에 집중할 수 있어요.':'리더에게 근거를 제시해 데모 범위를 조정할 수 있어요. 직원 경로에서는 회사 예산을 직접 집행하지 않아요.',[{label:founder?'외부 제작 지원 요청':'테스트 근거를 모아 우선순위 제안',effect:founder?'1구간 · 180만 · 완성도 +10 · 피로 +3':'1구간 · 완성도 +4 · 신뢰 +6 · 피로 +5',run:()=>{if(founder&&state.money<200){show('자금이 부족해요','운영 비용을 포함해 200만이 필요해요. 범위를 조정하는 안을 선택해 주세요.');return}advance(1,founder?{money:-180,quality:10,fatigue:3,xp:3}:{quality:4,trust:6,fatigue:5,xp:4},founder?'외부 지원으로 제작 속도를 높였다. 운영 자금이 줄었다.':'관찰한 근거로 개선안을 제안해 팀의 신뢰를 얻었다.')}},{label:'핵심 기능에 집중하도록 범위 조정',effect:'1구간 · 안정성 +6 · 신뢰 +3 · 피로 +2',run:()=>advance(1,{stability:6,trust:3,fatigue:2,xp:3},'우선순위를 정리해 팀이 핵심 경험에 집중할 수 있게 했다.')}])}}
function ending(){const score=Math.round(state.quality*.45+state.stability*.35+state.trust*.2),grade=score>=80?'기대 이상의 첫 공개':score>=55?'가능성을 보여준 첫 공개':'배울 것이 많았던 첫 공개';show(grade,`28일의 개발이 끝났어요. 완성도 ${state.quality}, 안정성 ${state.stability}, 팀 신뢰 ${state.trust}. 종합 반응은 ${score}점이에요. ${state.money===0?'자금이 소진되어 다음 제작에는 투자나 비용 조정이 필요해요. ':''}${score>=80?'유저들이 다음 버전을 기다리고 있어요.':score>=55?'핵심 재미는 전달됐지만 다음 버전에서 개선할 점이 남았어요.':'공개 반응을 바탕으로 핵심 경험과 안정성을 다시 다듬어야 해요.'} 이 프로토타입의 플레이 범위는 첫 데모까지이며, 정식 출시와 라이브 서비스는 이후 확장할 단계예요.`)}
function renderOther(){const el=$('#otherView');$('#viewTitle').textContent={project:'하나의 게임이 만들어지는 과정.',team:'좋은 게임은 함께 만드니까.',journal:'우리의 선택이 쌓이는 곳.'}[view];if(view==='project')el.innerHTML=`<div class="report"><h3>별빛 우체부</h3><p>별 사이를 여행하며 편지를 배달하는 탐험 게임. 첫 공개 데모에서는 이동, 배달, 작은 발견의 재미를 검증합니다.</p><p>현재 단계: ${stages[stage()]}<br>안정성: ${state.stability}% · 전문 경험: ${state.xp}<br>공개 일정: 28일차 종료</p></div><div class="report"><h3>개발 로드맵</h3><p>아이디어 → 프로토타입 → 프리 데모 → 공개 데모 → 본 제작 → 출시 준비 → 런칭 → 라이브 서비스</p><p>이번 플레이에서는 첫 공개 데모까지 진행할 수 있어요. 이후 단계는 기획된 확장 범위입니다.</p></div>`;if(view==='team')el.innerHTML=[['지민','기획','핵심 재미와 플레이 흐름을 설계해요.'],['도윤','프로그래밍','게임 시스템과 개발 도구를 만들어요.'],['하린','아트','별빛 우체부의 세계를 그려요.'],['수현','QA','플레이 속 숨은 위험을 찾아요.'],['유진','사업·마케팅','게임과 유저가 만나는 방법을 고민해요.']].map(([n,r,d])=>`<div class="report"><h3>${n} <small>· ${r}</small></h3><p>${d}</p><button class="quiet" data-chat="${n}">사무실에서 위치 확인</button></div>`).join('');if(view==='journal'){el.replaceChildren();state.logs.forEach(l=>{let p=document.createElement('div');p.className='journal-entry';p.textContent=l;el.append(p)})}el.querySelectorAll('[data-chat]').forEach(b=>b.onclick=()=>show(b.dataset.chat+'의 이야기','“우리 게임을 처음 만나는 사람의 입장에서 보면, 익숙해서 놓친 문제가 보이더라고요. 함께 빌드를 확인해 볼까요?”',[{label:'함께 검토하기',effect:'1구간 · 팀 신뢰 +8 · 완성도 +3',run:()=>advance(1,{trust:8,quality:3,fatigue:4,xp:3},'동료와 빌드를 검토하며 서로의 관점을 배웠다.')}]))}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));$('#officeView').hidden=view!=='office';$('#otherView').hidden=view==='office';$('#viewTitle').textContent='오늘도, 좋은 게임을 만들자.';if(view!=='office')renderOther()});$('#closeDetail').onclick=()=>$('#detail').close();$('#newGame').onclick=()=>$('#setup').showModal();$('#setup').addEventListener('cancel',e=>{if(!state)e.preventDefault()});$('#setupForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state=fresh(f.get('name').trim()||'새봄',f.get('role'),f.get('path'));$('#setup').close();render();$('#messageTitle').textContent='첫 출근을 환영해요';$('#message').textContent=state.path==='founder'?'공동 창업자로서 실무와 자원 배분을 함께 맡아요. 첫 공개까지 회사를 이끌어 보세요.':'담당 업무와 협업으로 전문성과 신뢰를 쌓아 보세요.'};$('#rest').onclick=()=>{if(state.done)return ending();show('잠깐 쉬어가요','커피 한 잔과 산책으로 다시 집중할 힘을 얻어요.',[{label:'휴식하기',effect:'1구간 · 피로 −22',run:()=>advance(1,{fatigue:-22},'충분히 쉬었다. 다시 집중할 여유가 생겼다.')}])};

